mapper.update:
UPDATE pet_order SET current_refund_application_id=#{application},refund_application_status='PENDING_MERCHANT',version=version+1,updated_at=#{at}
WHERE id=#{order} AND store_id=#{store} AND version=#{oldVersion} AND refund_order_id IS NULL AND refunded_amount=0
 AND (current_refund_application_id IS NULL OR refund_application_status='REJECTED')

UPDATE order_refund_application_proof SET application_status=#{status},application_version=#{applicationVersion},decision_id=#{decision},decided_at=#{at}
WHERE application_id=#{application} AND order_id=#{order} AND store_id=#{store} AND application_status='PENDING_MERCHANT'
 AND decision_id IS NULL AND application_version=#{oldApplicationVersion}

UPDATE pet_order SET refund_application_status=#{status},version=version+1,updated_at=#{at}
WHERE id=#{order} AND store_id=#{store} AND version=#{oldVersion} AND current_refund_application_id=#{application}
 AND refund_application_status='PENDING_MERCHANT' AND refund_order_id IS NULL AND refunded_amount=0

UPDATE pet_order SET refund_order_id=#{refund},version=version+1,updated_at=#{at}
WHERE id=#{order} AND store_id=#{store} AND version=#{oldVersion} AND current_refund_application_id=#{application}
 AND refund_application_status IN ('APPROVED','AUTO_APPROVED') AND refund_order_id IS NULL AND refunded_amount=0

UPDATE pet_order SET refunded_amount=#{amount},version=version+1,updated_at=#{at}
WHERE id=#{order} AND store_id=#{store} AND refund_order_id=#{refund} AND refunded_amount=0
 AND order_stage IN ('PENDING_SERVICE','COMPLETED') AND payment_status='PAID'
